const PATTERNS = [
  { name: 'ЭЛЕКТРОННАЯ ПОЧТА', re: /[\w.+-]+@[\w-]+\.[\w.]{2,}/g, token: '[ЭЛЕКТРОННАЯ_ПОЧТА]' },
  { name: 'БАНКОВСКИЙ СЧЁТ',   re: /\b[A-Z]{2}\d{2}[A-Z0-9]{10,28}\b/g, token: '[СЧЁТ]' },
  { name: 'НОМЕР ПОЛИСА',      re: /\b[A-Z]\d{9}\b/g, token: '[ПОЛИС]' },
  { name: 'ТЕЛЕФОН',           re: /\+?\d[\d\s\-()]{7,}\d/g, token: '[ТЕЛЕФОН]' },
  { name: 'ДАТА РОЖДЕНИЯ',     re: /\b\d{1,2}[.\-\/]\d{1,2}[.\-\/](?:19\d{2}|200\d)\b/g, token: '[ДАТА_РОЖДЕНИЯ]' }
];

const esc = (x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  let t = String(j.text || '');
  const found = [];

  const nameParts = String(j.patient_name || '').split(/[\s,.]+/).filter(p => p.length >= 3);
  for (const p of nameParts) {
    const re = new RegExp(esc(p), 'gi');
    if (t.match(re)) { found.push('ИМЯ'); t = t.replace(re, '[ИМЯ]'); }
  }

  for (const p of PATTERNS) {
    if (t.match(p.re)) { found.push(p.name); t = t.replace(p.re, p.token); }
  }

  const leaks = [];
  for (const p of nameParts) {
    if (t.match(new RegExp(esc(p), 'i'))) leaks.push('имя: ' + p);
  }
  if (t.match(/[\w.+-]+@[\w-]+\.[\w.]{2,}/)) leaks.push('электронная почта');
  if (t.match(/\+?\d[\d\s\-()]{7,}\d/)) leaks.push('телефон');

  out.push({ json: Object.assign({}, j, {
    text_anonym: t,
    pii_kategorien: [...new Set(found)].join(', ') || 'не обнаружено',
    pii_anzahl: found.length,
    pii_leaks: leaks.join('; ') || '—',
    pii_sauber: leaks.length === 0
  })});
}

return out;

